// Times sets number of times MigrationObserver.Duration should be invoked
func (mmDuration *mMigrationObserverMockDuration) Times(n uint64) *mMigrationObserverMockDuration {
	if n == 0 {
		mmDuration.mock.t.Fatalf("Times of MigrationObserverMock.Duration mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmDuration.expectedInvocations, n)
	mmDuration.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmDuration
}

func (mmDuration *mMigrationObserverMockDuration) invocationsDone() bool {
	if len(mmDuration.expectations) == 0 && mmDuration.defaultExpectation == nil && mmDuration.mock.funcDuration == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmDuration.mock.afterDurationCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmDuration.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Duration implements mm_service.MigrationObserver
func (mmDuration *MigrationObserverMock) Duration(ctx context.Context, elapsed time.Duration) {
	mm_atomic.AddUint64(&mmDuration.beforeDurationCounter, 1)
	defer mm_atomic.AddUint64(&mmDuration.afterDurationCounter, 1)

	mmDuration.t.Helper()

	if mmDuration.inspectFuncDuration != nil {
		mmDuration.inspectFuncDuration(ctx, elapsed)
	}

	mm_params := MigrationObserverMockDurationParams{ctx, elapsed}

	// Record call args
	mmDuration.DurationMock.mutex.Lock()
	mmDuration.DurationMock.callArgs = append(mmDuration.DurationMock.callArgs, &mm_params)
	mmDuration.DurationMock.mutex.Unlock()

	for _, e := range mmDuration.DurationMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return
		}
	}

	if mmDuration.DurationMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmDuration.DurationMock.defaultExpectation.Counter, 1)
		mm_want := mmDuration.DurationMock.defaultExpectation.params
		mm_want_ptrs := mmDuration.DurationMock.defaultExpectation.paramPtrs

		mm_got := MigrationObserverMockDurationParams{ctx, elapsed}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmDuration.t.Errorf("MigrationObserverMock.Duration got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmDuration.DurationMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.elapsed != nil && !minimock.Equal(*mm_want_ptrs.elapsed, mm_got.elapsed) {
				mmDuration.t.Errorf("MigrationObserverMock.Duration got unexpected parameter elapsed, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmDuration.DurationMock.defaultExpectation.expectationOrigins.originElapsed, *mm_want_ptrs.elapsed, mm_got.elapsed, minimock.Diff(*mm_want_ptrs.elapsed, mm_got.elapsed))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmDuration.t.Errorf("MigrationObserverMock.Duration got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmDuration.DurationMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		return

	}
	if mmDuration.funcDuration != nil {
		mmDuration.funcDuration(ctx, elapsed)
		return
	}
	mmDuration.t.Fatalf("Unexpected call to MigrationObserverMock.Duration. %v %v", ctx, elapsed)

}

// DurationAfterCounter returns a count of finished MigrationObserverMock.Duration invocations
func (mmDuration *MigrationObserverMock) DurationAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmDuration.afterDurationCounter)
}

// DurationBeforeCounter returns a count of MigrationObserverMock.Duration invocations
func (mmDuration *MigrationObserverMock) DurationBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmDuration.beforeDurationCounter)
}

// Calls returns a list of arguments used in each call to MigrationObserverMock.Duration.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmDuration *mMigrationObserverMockDuration) Calls() []*MigrationObserverMockDurationParams {
	mmDuration.mutex.RLock()

	argCopy := make([]*MigrationObserverMockDurationParams, len(mmDuration.callArgs))
	copy(argCopy, mmDuration.callArgs)

	mmDuration.mutex.RUnlock()

	return argCopy
}

// MinimockDurationDone returns true if the count of the Duration invocations corresponds
// the number of defined expectations
func (m *MigrationObserverMock) MinimockDurationDone() bool {
	if m.DurationMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.DurationMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.DurationMock.invocationsDone()
}

// MinimockDurationInspect logs each unmet expectation
func (m *MigrationObserverMock) MinimockDurationInspect() {
	for _, e := range m.DurationMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to MigrationObserverMock.Duration at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterDurationCounter := mm_atomic.LoadUint64(&m.afterDurationCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.DurationMock.defaultExpectation != nil && afterDurationCounter < 1 {
		if m.DurationMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to MigrationObserverMock.Duration at\n%s", m.DurationMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to MigrationObserverMock.Duration at\n%s with params: %#v", m.DurationMock.defaultExpectation.expectationOrigins.origin, *m.DurationMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcDuration != nil && afterDurationCounter < 1 {
		m.t.Errorf("Expected call to MigrationObserverMock.Duration at\n%s", m.funcDurationOrigin)
	}

	if !m.DurationMock.invocationsDone() && afterDurationCounter > 0 {
		m.t.Errorf("Expected %d calls to MigrationObserverMock.Duration at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.DurationMock.expectedInvocations), m.DurationMock.expectedInvocationsOrigin, afterDurationCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *MigrationObserverMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockActionsInspect()

			m.MinimockCleanupInspect()

			m.MinimockCopiedInspect()

			m.MinimockDurationInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *MigrationObserverMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *MigrationObserverMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockActionsDone() &&
		m.MinimockCleanupDone() &&
		m.MinimockCopiedDone() &&
		m.MinimockDurationDone()
}
